"""Parallel replay-bench sweeps on nayeem's recorded real-sim fields, with plan-config variants and paired statistics.

    python tools/replay_batch.py SPEC.json OUT.jsonl [workers]      # workers: default one per physical core

SPEC.json:
    {"lab": "../STU4-lab",                       # a clone of codernayeem/STU4-lab, fields rebuilt by restore_fields.py
     "fields": "fields_all41.json",              # a field list in the lab, a list of field folder names, or
                                                 # {"world": 26}: fields generated by tools/phobos_world.py
     "seeds": [21, 22],
     "configs": {"v5":   {"planner": "velocity_obstacle"},
                 "ours": {"planner": "velocity_obstacle", "variant": "ours"},          # configs/ours.json of that plan
                 "rw3":  {"planner": "velocity_obstacle", "cfg": {"risk_weight": 3.0}}, # plan-config keys
                 "x":    {"set": {"Core.FRAME": false}, "burn": "direct"}}}          # module attributes, burn law
One fresh process per run, so nothing leaks between configs (nayeem's batch.py fix). Prints one summary line per config
and, against the first config, the paired mean difference on the same fields and seeds with its standard error.
"""
import json
import multiprocessing as mp
import os
import sys
from pathlib import Path

import numpy as np

REPO = Path(__file__).resolve().parent.parent


def _fields(spec):
    lab = (REPO / spec.get("lab", "../STU4-lab")).resolve()
    names = spec["fields"]
    if isinstance(names, str):
        names = json.load(open(lab / names))
    if isinstance(names, dict):                  # {"world": N}: N fields generated from the world definition
        return [f"world:{k}" for k in range(names["world"])]
    return [n if n.startswith("world:") else str(lab / "runs" / Path(n).name) for n in names]


def job(args):
    name, cfg, field, seed = args
    sys.path.insert(0, str(REPO)); os.chdir(REPO)
    from tools import replay_bench as RB
    from Systems import Actuation, BasicController, Core, Flight, Radar
    from Systems.plans import get_config
    from Systems.plans.common import read_config_json
    mods = dict(Core=Core, Radar=Radar, Actuation=Actuation, Flight=Flight, BasicController=BasicController)
    for k, v in cfg.get("set", {}).items():
        m, a = k.split(".", 1); setattr(mods[m], a, tuple(v) if isinstance(v, list) else v)
    planner = cfg.get("planner", BasicController.PLANNER)
    plan_cfg = dict(get_config(planner))
    if cfg.get("variant"):
        plan_dir = next((REPO / "Systems" / "plans").glob(f"plan_*_{planner}"))
        plan_cfg.update(read_config_json(plan_dir / "configs" / f"{cfg['variant']}.json"))
    plan_cfg.update(cfg.get("cfg", {}))
    try:
        if field.startswith("world:"):
            from tools.phobos_world import WorldField
            fld = WorldField(int(field.split(":")[1]))
        else:
            fld = RB.Field(field)
        res, _ = RB.run(fld, seed, planner, cfg.get("burn"), tmax=cfg.get("tmax", 380.0),     # None: the plan config's burn
                        oracle=cfg.get("oracle", False), config=plan_cfg)
    except Exception as e:                       # one broken run must not stop a sweep
        res = dict(error=repr(e), seed=seed, field=Path(field).name[:13])
    res["cfg"] = name
    return res


def summary(rows):
    """Per config: n, arrived, hits, mean/min score, fuel, T; then paired differences against the first config."""
    by = {}
    for r in rows:
        by.setdefault(r["cfg"], {})[(r.get("field"), r.get("seed"))] = r
    names = list(by); base = by[names[0]]; out = []
    for n in names:
        rs = list(by[n].values()); sc = np.array([r.get("score", np.nan) if r.get("arrived") else np.nan for r in rs], float)
        line = (f"{n:20s} n={len(rs):3d} arrived {sum(bool(r.get('arrived')) for r in rs)} hits {sum((r.get('damage') or 0) > 0 for r in rs)} "
                f"mean {np.nanmean(sc):6.1f} min {np.nanmin(sc):7.1f} fuel {np.nanmean([r.get('fuel', np.nan) for r in rs]):5.1f} "
                f"T {np.nanmean([r.get('T') or np.nan for r in rs]):6.1f}")
        if n != names[0]:
            d = np.array([by[n][k].get("score", np.nan) - base[k].get("score", np.nan) for k in by[n] if k in base], float)
            d = d[np.isfinite(d)]
            if len(d) > 1:
                line += f" | vs {names[0]}: {d.mean():+.1f} +/- {d.std(ddof=1) / np.sqrt(len(d)):.1f} (n={len(d)})"
        out.append(line)
    return "\n".join(out)


if __name__ == "__main__":
    spec = json.load(open(sys.argv[1])); out_path = sys.argv[2]; W = int(sys.argv[3]) if len(sys.argv) > 3 else max(1, (os.cpu_count() or 2) // 2)   # one per physical core: 12 on 6 cores ran 2x slower
    jobs = [(n, c, f, s) for n, c in spec["configs"].items() for f in _fields(spec) for s in spec["seeds"]]
    rows = []
    with open(out_path, "a") as out, mp.Pool(W, maxtasksperchild=1) as pool:
        for r in pool.imap_unordered(job, jobs):
            out.write(json.dumps(r, default=str) + "\n"); out.flush(); rows.append(r)
    order = {n: i for i, n in enumerate(spec["configs"])}
    print(summary(sorted(rows, key=lambda r: order[r["cfg"]])), flush=True)
